// PROTOTYPE - NOT FOR PRODUCTION
// EN layer of data/tutorial.js (js/i18n.js). One text per path, the French beside it.
// null: still to translate. Written by node tools/i18n.js extract en; translations already here are kept.
I18N.add('en', {
  'tutorial.guide.name': 'Aveline', // Aveline
  'tutorial.guide.title': 'Master Builder', // Maîtresse bâtisseuse
  'tutorial.title': 'First Steps', // Premiers pas
  'tutorial.strings.tuto_lesson_step_short': '{title} · step {n} / {all}', // {title} · étape {n} / {all}
  'tutorial.strings.tuto_order_gift': '{name} has filled this order for you, just this once.', // {name} a rempli cette commande pour vous, cette fois.
  'tutorial.steps[hello].say[0]': 'Welcome to Aubeval, Mayor! I’m Aveline, your master builder. A town hall, a clearing… and everything else still to build.', // Bienvenue à Aubeval, bourgmestre ! Je suis Aveline, votre maîtresse bâtisseuse. Un hôtel de ville, une clairière… et tout le reste à bâtir.
  'tutorial.steps[hello].say[1]': 'I’ll show you the essentials, step by step. Follow the golden arrow: it always points to where you should click.', // Je vous montre l’essentiel, pas à pas. Suivez la flèche dorée : elle indique toujours où cliquer.
  'tutorial.steps[view].say[0]': 'First, have a look around: hold the click on the map and drag it.', // D’abord, regardez autour de vous : maintenez le clic sur la carte et faites-la glisser.
  'tutorial.steps[view].task': 'Hold the click and drag the map.', // Maintenez le clic et faites glisser la carte.
  'tutorial.steps[wood].say[0].text': 'Perfect! The wheel zooms, and so do these buttons. The C key always brings the view back to the village.', // Parfait ! La molette zoome, et ces boutons aussi. La touche C ramène toujours la vue au village.
  'tutorial.steps[wood].say[1]': 'It all begins with wood. Click the trees: every stroke of the axe brings in a log.', // Tout commence par du bois. Cliquez sur les arbres : chaque coup de hache rapporte une bûche.
  'tutorial.steps[wood].task': 'Click trees to gather 5 wood.', // Cliquez sur des arbres pour récolter 5 bois.
  'tutorial.steps[hut].say[0].text': 'Your stores are shown up there. But chopping by hand is slow work: let’s build a woodcutter’s hut.', // Vos réserves s’affichent là-haut. Mais couper à la main, c’est long : bâtissons une cabane de bûcheron.
  'tutorial.steps[hut].say[1]': 'The golden rule: a building only works if it touches a paved path linked to the town hall. Set it on the glowing spot.', // La règle d’or : un bâtiment ne travaille que s’il touche un chemin pavé relié à l’hôtel de ville. Posez-la sur la place qui brille.
  'tutorial.steps[hut].task': 'Take the “Woodcutter” card, then place it beside the path.', // Prenez la carte « Bûcheron », puis posez-la au bord du chemin.
  'tutorial.steps[path].say[0].text': 'See the “+1.0/s” under the wood? The village works on its own now. And here are a few logs from my own store.', // Vous voyez le « +1,0/s » sous le bois ? Le village travaille seul, maintenant. Et voici quelques bûches de ma réserve.
  'tutorial.steps[path].say[1]': 'To build further out, we extend the street. Take the Path tool, then drag over the marked tiles: 1 wood per tile.', // Pour bâtir plus loin, on prolonge la rue. Prenez l’outil Chemin, puis glissez sur les cases marquées : 1 bois par case.
  'tutorial.steps[path].task': 'Land tab, “Path” card: pave the marked tiles.', // Onglet Terrain, carte « Chemin » : tracez les cases marquées.
  'tutorial.steps[sawmill].say[0]': 'A fine street! Everything along it will be able to work.', // Belle rue ! Tout ce qui la borde pourra travailler.
  'tutorial.steps[sawmill].say[1]': 'Now for production chains: the Sawmill turns wood into planks. Place it along a path.', // Passons aux chaînes de production : la Scierie change le bois en planches. Posez-la le long d’un chemin.
  'tutorial.steps[sawmill].task': 'Take the “Sawmill” card, then place it beside a path.', // Prenez la carte « Scierie », puis posez-la au bord d’un chemin.
  'tutorial.steps[forge].say[0].text': 'Wood, then planks: that’s a chain. Each building feeds the next.', // Du bois, puis des planches : voilà une chaîne. Chaque bâtiment nourrit le suivant.
  'tutorial.steps[forge].say[1]': 'With 8 planks, we can build the Forge. That’s where the village arms its hero, {hero}.', // Avec 8 planches, on bâtit la Forge. C’est là que le village arme {g:son héros|son héroïne}, {hero}.
  'tutorial.steps[forge].task': 'Take the “Forge” card (8 planks), then place it beside a path.', // Prenez la carte « Forge » (8 planches), puis posez-la au bord d’un chemin.
  'tutorial.steps[sword].say[0]': 'Clicking a building opens its panel: there you upgrade it, move it… and at the Forge, you forge.', // Un clic sur un bâtiment ouvre son panneau : on l’y améliore, on le déplace… et à la Forge, on y forge.
  'tutorial.steps[sword].task': 'Click the Forge, then forge the Apprentice’s Blade.', // Cliquez la Forge, puis forgez la Lame d’apprenti.
  'tutorial.steps[equip].say[0]': 'The blade is ready! Now to put it in {hero}’s hands.', // La lame est prête ! Il reste à la mettre dans les mains {de_hero}.
  'tutorial.steps[equip].task': 'Open the Hero sheet, then equip the blade.', // Ouvrez la fiche {g:du Héros|de l’Héroïne}, puis équipez la lame.
  'tutorial.steps[fight].say[0]': '{hero} is armed by your village. Two goblins are prowling round the stores: let’s send {g:him|her} out.', // {hero} est {g:armé|armée} par votre village. Deux gobelins rôdent autour des réserves : envoyons-{g:le|la}.
  'tutorial.steps[fight].say[1]': 'In battle, your village becomes a deck of cards: each building sends its own. Three points of Breath per turn to play them.', // En combat, votre village devient un paquet de cartes : chaque bâtiment envoie la sienne. Trois points de souffle par tour pour en jouer.
  'tutorial.steps[fight].say[2]': 'And when a goblin strikes, press Space the moment the ring touches the golden circle: that’s a parry!', // Et quand un gobelin frappe, pressez Espace à l’instant où l’anneau touche le cercle doré : c’est une parade !
  'tutorial.steps[fight].task': 'Open the Quests, then “Go to battle”.', // Ouvrez les Quêtes, puis « Partir au combat ».
  'tutorial.steps[bye].say[0].text': 'Victory! But hark, that horn: the goblins have pitched their camp. The countdown to the first raid is here.', // Victoire ! Mais écoutez cette corne : les gobelins ont dressé leur camp. Le compte à rebours du premier raid est ici.
  'tutorial.steps[bye].say[1].text': 'The quests, here, will always tell you what to do next. And I’ll come back to show you each new thing as it opens: houses, defence, trades…', // Les quêtes, ici, vous diront toujours quoi faire ensuite. Et je reviendrai vous montrer chaque nouveauté au moment où elle s’ouvre : les maisons, la défense, les métiers…
  'tutorial.steps[bye].say[2]': 'Aubeval is yours, Mayor. Here’s a little something to get you started!', // Aubeval est à vous, bourgmestre. Voici de quoi bien démarrer !
  'tutorial.lessons[horn].title': 'The Horn', // La corne
  'tutorial.lessons[horn].about': 'Traps, and what happens during a raid.', // Les pièges, et ce qui se passe pendant un raid.
  'tutorial.lessons[horn].steps[traps].say[0].text': 'The horn! Goblins will soon leave their camp: the countdown has turned red.', // La corne ! Des gobelins sortent bientôt de leur camp : le compte à rebours a rougi.
  'tutorial.lessons[horn].steps[traps].say[1].text': 'From the horn to the end of the raid, you lay traps in their path: stakes, a pitch pool that slows them, a powder keg that explodes.', // De la corne à la fin du raid, on pose des pièges sur leur route : des pieux, une mare de poix qui les ralentit, un baril de poudre qui explose.
  'tutorial.lessons[horn].steps[traps].task': 'Defence tab: take the “Stakes” and place them on the glowing tile, on the camp’s road.', // Onglet Défense : prenez les « Pieux » et posez-les sur la case qui brille, sur la route du camp.
  'tutorial.lessons[horn].steps[after].say[0]': 'Traps vanish at the end of the raid. If the road is out of sight, the red marker at the edge of the screen leads there.', // Les pièges s’en vont à la fin du raid. Si la route est hors de vue, le repère rouge au bord de l’écran y mène.
  'tutorial.lessons[horn].steps[after].say[1]': 'A raider who reaches the town hall steals a share of your stores, and a lost raid damages buildings: repair them from their panel. Courage, Mayor!', // Un pillard qui atteint l’hôtel de ville vole une part de vos réserves, et un raid perdu abîme des bâtiments : ils se réparent depuis leur panneau. Courage, bourgmestre !
  'tutorial.lessons[siege].title': 'The Siege', // Le siège
  'tutorial.lessons[siege].about': 'A siege’s warlord, what he changes, and the duel that challenges him.', // Le chef de guerre d’un siège, ce qu’il change, et le duel qui le défie.
  'tutorial.lessons[siege].steps[lord].say[0].text': 'Three blasts of the horn: this time, it’s a siege. A larger, tougher column, led by a warlord.', // Trois coups de corne : cette fois, c’est un siège. Une colonne plus nombreuse et plus dure, menée par un chef de guerre.
  'tutorial.lessons[siege].steps[lord].say[1].text': 'His plate, under the countdown, names him and tells what he changes. This one is {lord}. {trait}', // Sa plaque, sous le compte à rebours, le nomme et dit ce qu’il change. Celui-ci, c’est {lord}. {trait}
  'tutorial.lessons[siege].steps[lord].say[2]': 'They come in turn, stronger with each siege: Morgash breaks walls, Zhara doubles her shamans’ healing, Urgak brings his brutes, Skrit sets the column running.', // Ils viennent à tour de rôle, plus forts à chaque siège : Morgash brise les murs, Zhara double les soins de ses chamans, Urgak amène ses brutes, Skrit fait courir sa colonne.
  'tutorial.lessons[siege].steps[duel].say[0].text': '“Challenge {lord}”: {hero} faces him alone, with cards. Only once per siege, from the horn to the end.', // « Défier {lord} » : {hero} l’affronte {g:seul|seule}, aux cartes. Une seule fois par siège, de la corne jusqu’à la fin.
  'tutorial.lessons[siege].steps[duel].say[1]': 'Win, and the warlord is out of the fight and his column loses heart: less health, less speed, and deserters. Lost or never tried, he marches with it and counts for {n:warlord_leaks} at your gate.', // Vainqueur, le chef est hors de combat et sa colonne perd courage : moins de vie, moins vite, et des fuyards. Perdu ou pas tenté, il marche avec elle et compte pour {n:warlord_leaks} à votre porte.
  'tutorial.lessons[siege].steps[duel].say[2]': 'A siege plunders more than a raid, and breaks more: traps, soldiers and ramparts count double. Repelled, it pays a real bounty. It’s up to you whether {hero} is ready for the duel!', // Un siège pille plus qu’un raid, et casse davantage : pièges, soldats et remparts comptent double. Repoussé, il paie une vraie prime. À vous de voir si {hero} est {g:prêt|prête} pour le duel !
  'tutorial.lessons[houses].title': 'Inhabitants', // Des habitants
  'tutorial.lessons[houses].about': 'Houses, their inhabitants, their class and their style.', // Les maisons, leurs habitants, leur classe et leur style.
  'tutorial.lessons[houses].steps[house].say[0]': 'A house lodges inhabitants. They pay their tax in gold, and their number opens new buildings.', // Une maison loge des habitants. Ils paient l’impôt en or, et leur nombre ouvre de nouveaux bâtiments.
  'tutorial.lessons[houses].steps[house].say[1].text': 'Houses are in the Housing tab. Like the workshops, they must touch a path.', // Les maisons sont dans l’onglet Habitat. Comme les ateliers, elles doivent toucher un chemin.
  'tutorial.lessons[houses].steps[house].say[2]': 'I’ll always show you the spot I’d choose: away from the workshops’ noise, near the other houses, with room around it. You’re free to pick another.', // Je vous montre toujours la place que je choisirais : loin du bruit des ateliers, près des autres maisons, avec de l’espace autour. Libre à vous d’en prendre une autre.
  'tutorial.lessons[houses].steps[house].task': 'Take the “House” card, then place it on the glowing spot.', // Prenez la carte « Maison », puis posez-la sur la place qui brille.
  'tutorial.lessons[houses].steps[tenants].say[0]': 'Let’s open it and see who lives there.', // Ouvrons-la pour voir qui y vit.
  'tutorial.lessons[houses].steps[tenants].task': 'Click the house, then the “Inhabitants” tab.', // Cliquez la maison, puis l’onglet « Habitants ».
  'tutorial.lessons[houses].steps[look].say[0]': 'These are Peasants. They eat bread: well fed, they are satisfied and pay their full tax.', // Ce sont des Paysans. Ils mangent du pain : bien nourris, ils sont satisfaits et paient tout leur impôt.
  'tutorial.lessons[houses].steps[look].say[1]': 'Later, with coffee and a Café down the street, they’ll rise to Artisans, then Burghers, Merchants and Nobles. The house grows with them.', // Plus tard, avec du café et un Café au bout de la rue, ils s’élèveront en Artisans, puis Bourgeois, Négociants et Nobles. La maison grandit avec eux.
  'tutorial.lessons[houses].steps[look].task': 'Open the “Appearance” tab.', // Ouvrez l’onglet « Apparence ».
  'tutorial.lessons[houses].steps[style].say[0].text': 'Here, its style can be changed at any time, for free: timber-framed, stone or wood. The town hall too. Below, the house for each class.', // Ici, son style se change à tout moment, gratuitement : colombages, pierre ou bois. L’hôtel de ville aussi. En dessous, la maison à chaque classe.
  'tutorial.lessons[defense].title': 'Towers and Ramparts', // Tours et remparts
  'tutorial.lessons[defense].about': 'Watchtowers, ramparts (and upgrading them all at once), the safe zone and the raid countdown.', // Tours de guet, remparts (et les améliorer d’un coup), zone sûre et compte à rebours du raid.
  'tutorial.lessons[defense].steps[tower].say[0].text': 'The goblins will come. This countdown tells you when; “Call” brings them at once, for a bounty.', // Les gobelins viendront. Ce compte à rebours dit quand ; « Appeler » les fait venir tout de suite, contre une prime.
  'tutorial.lessons[defense].steps[tower].say[1]': 'They always leave their camp and march on the town hall. A watchtower shoots at any that pass within its range.', // Ils sortent toujours de leur camp et marchent vers l’hôtel de ville. Une tour de guet tire sur ceux qui passent à sa portée.
  'tutorial.lessons[defense].steps[tower].task': 'Defence tab: place a “Watchtower” on the glowing spot (or elsewhere).', // Onglet Défense : posez une « Tour de guet » sur la place qui brille (ou ailleurs).
  'tutorial.lessons[defense].steps[wall].say[0]': 'The circle round the tower, while you hold it, shows its range. Now, a rampart.', // Le cercle autour de la tour, quand on la tient, montre sa portée. Maintenant, un rempart.
  'tutorial.lessons[defense].steps[wall].say[1]': 'Take the Palisade, hold the click and drag: the whole line is built when you let go. Shift + drag draws an enclosure, and right-click cancels.', // Prenez la Palissade, maintenez le clic et glissez : tout le tracé se bâtit au relâchement. Maj + glisser trace une enceinte, et le clic droit annule.
  'tutorial.lessons[defense].steps[wall].task': 'Draw a rampart of at least 3 sections by dragging over the glowing tiles.', // Tracez un rempart d’au moins 3 tronçons, en glissant sur les cases qui brillent.
  'tutorial.lessons[defense].steps[safe].say[0]': 'Raiders must break it or go round it, while your towers shoot.', // Les pillards doivent le briser ou le contourner, pendant que vos tours tirent.
  'tutorial.lessons[defense].steps[safe].say[1]': 'And while you hold a building, the pale circle round the town hall is the safe zone: no raider appears there. Each level of the town hall widens it.', // Et quand vous tenez un bâtiment, le cercle clair autour de l’hôtel de ville est la zone sûre : aucun pillard n’y apparaît. Chaque niveau de l’hôtel de ville l’élargit.
  'tutorial.lessons[defense].steps[rampart].say[0]': 'A rampart is upgraded in one go, not palisade by palisade. Open one of its palisades.', // Un rempart s’améliore d’un seul coup, pas palissade par palissade. Ouvrez l’une des siennes.
  'tutorial.lessons[defense].steps[rampart].task': 'Click a palisade of your rampart, then “Whole rampart”.', // Cliquez une palissade de votre rempart, puis « Tout le rempart ».
  'tutorial.lessons[defense].steps[rampart_done].say[0].text': 'Every linked palisade that was at that level has gone up, and is sturdier. “Upgrade” raises only one.', // Toutes les palissades reliées qui étaient à ce niveau y sont passées, et sont plus solides. « Améliorer » n’en monte qu’une.
  'tutorial.lessons[farm].title': 'Wheat', // Le blé
  'tutorial.lessons[farm].about': 'The Farm, first link in the bread chain.', // La Ferme, premier maillon du pain.
  'tutorial.lessons[farm].steps[farm].say[0]': 'Your Peasants will hunger for bread. Bread begins in the field: the Farm grows wheat.', // Vos Paysans auront faim de pain. Le pain commence au champ : la Ferme cultive le blé.
  'tutorial.lessons[farm].steps[farm].task': 'Production tab: place a “Farm” on the glowing spot.', // Onglet Production : posez une « Ferme » sur la place qui brille.
  'tutorial.lessons[farm].steps[next].say[0]': 'At 8 inhabitants, the Bakery will turn this wheat into bread. I’ll come back to show it to you.', // À 8 habitants, la Boulangerie changera ce blé en pain. Je reviendrai vous la montrer.
  'tutorial.lessons[workers].title': 'Trades', // Les métiers
  'tutorial.lessons[workers].about': 'Training workers who gather on their own: woodcutter, miner, harvester.', // Former des ouvriers qui récoltent seuls : bûcheron, mineur, moissonneur.
  'tutorial.lessons[workers].steps[people].say[0]': 'Your free inhabitants can learn a trade. A worker works alone: you never have to guide him.', // Vos habitants libres peuvent apprendre un métier. Un ouvrier travaille seul : vous n’avez jamais à le guider.
  'tutorial.lessons[workers].steps[people].say[1].text': 'The People panel opens here, or with the K key.', // Le Peuple s’ouvre ici, ou avec la touche K.
  'tutorial.lessons[workers].steps[people].task': 'Open the People panel.', // Ouvrez le Peuple.
  'tutorial.lessons[workers].steps[train].say[0].text': 'The Woodcutter goes to the nearest tree and brings the wood back to a woodcutter’s hut.', // Le Bûcheron va à l’arbre le plus proche et rapporte le bois à une cabane de bûcheron.
  'tutorial.lessons[workers].steps[train].task': 'Train a “Woodcutter”.', // Formez un « Bûcheron ».
  'tutorial.lessons[workers].steps[trades].say[0]': 'Off he goes! The Miner will do the same with rocks and bring the stone to a quarry; the Harvester will reap at the farms and carry the wheat to the bakery.', // Le voilà en route ! Le Mineur fera de même avec les rochers et rapportera la pierre à une carrière ; le Moissonneur fauchera aux fermes et portera le blé à la boulangerie.
  'tutorial.lessons[workers].steps[trades].say[1]': 'The “−” sends a worker home: he becomes a free inhabitant again. And if he spots a raider, he runs for shelter at the town hall.', // Le « − » renvoie un ouvrier chez lui : il redevient un habitant libre. Et s’il voit un pillard, il court se mettre à l’abri à l’hôtel de ville.
  'tutorial.lessons[orders].title': 'Orders', // Les commandes
  'tutorial.lessons[orders].about': 'The inhabitants’ orders: reading, honouring and refusing them.', // Les commandes des habitants : les lire, les honorer, les refuser.
  'tutorial.lessons[orders].steps[open].say[0]': 'Your inhabitants have a request! They place orders with the town: three at a time (more as the city grows), and there will always be more.', // Vos habitants ont une demande ! Ils passent commande à la ville : trois à la fois (davantage quand la cité grandit), et il en viendra toujours.
  'tutorial.lessons[orders].steps[open].say[1].text': 'It all lives in the City panel: this button, or the G key.', // Tout cela se tient dans la Cité : ce bouton, ou la touche G.
  'tutorial.lessons[orders].steps[open].task': 'Open the City, then the “Orders” tab.', // Ouvrez la Cité, puis l’onglet « Commandes ».
  'tutorial.lessons[orders].steps[read].say[0].text': 'An order says who is asking, for what, and how far along you are. At the bottom, its pay: gold, and popularity for {hero}.', // Une commande dit qui demande, quoi, et où vous en êtes. En bas, sa paie : de l’or, et de la popularité pour {hero}.
  'tutorial.lessons[orders].steps[read].say[1]': 'Deliver goods, build, beautify a street, raise a house; repel a raid, win a battle, raze the camp; play at a keeper’s, explore a site: there’s something for every taste.', // Livrer des marchandises, bâtir, embellir une rue, élever une maison ; repousser un raid, gagner un combat, raser le camp ; jouer chez un tenancier, explorer un lieu : il y en a pour tous les goûts.
  'tutorial.lessons[orders].steps[read].say[2].text': '“Refuse” sends back an order you don’t fancy: another arrives {t:order_wait} later. Only one refusal every {t:order_refuse_cd}.', // « Refuser » renvoie une commande qui ne vous dit rien : une autre arrive {t:order_wait} plus tard. Un seul refus toutes les {t:order_refuse_cd}.
  'tutorial.lessons[orders].steps[honour].say[0]': 'When an order’s gauge is full, its button lights up. This one is ready: let’s cash it in!', // Quand la jauge d’une commande est pleine, son bouton s’allume. Celle-ci est prête : encaissons-la !
  'tutorial.lessons[orders].steps[honour].task': 'Click “Deliver” (or “Honour”).', // Cliquez « Livrer » (ou « Honorer »).
  'tutorial.lessons[orders].steps[after].say[0]': 'An honoured order makes way for the next, a little later. Each town rank asks for a certain number: keep an eye on them.', // Une commande honorée laisse sa place à la suivante, un peu plus tard. Chaque rang de la ville en demande un certain nombre : gardez-les à l’œil.
  'tutorial.lessons[bakery].title': 'Bread', // Le pain
  'tutorial.lessons[bakery].about': 'The Bakery, and the red plates that tell you what is missing.', // La Boulangerie, et les plaques rouges qui disent ce qui manque.
  'tutorial.lessons[bakery].steps[bakery].say[0]': 'Eight inhabitants: the Bakery opens. It bakes your farms’ wheat into bread, the need of all your houses.', // Huit habitants : la Boulangerie s’ouvre. Elle cuit le blé de vos fermes en pain, le besoin de toutes vos maisons.
  'tutorial.lessons[bakery].steps[bakery].task': 'Production tab: place a “Bakery” on the glowing spot.', // Onglet Production : posez une « Boulangerie » sur la place qui brille.
  'tutorial.lessons[bakery].steps[plates].say[0]': 'A house short of bread wears a red plate above its roof. These plates always tell you what is missing: a path, a resource, a service.', // Une maison qui manque de pain porte une plaque rouge au-dessus de son toit. Ces plaques disent toujours ce qui manque : un chemin, une ressource, un service.
  'tutorial.lessons[bakery].steps[plates].say[1]': 'Bread serves {hero} too: the Bakery sends {g:him|her} a Ration card in battle.', // Le pain sert aussi {hero} : la Boulangerie lui envoie une carte de Ration en combat.
  'tutorial.lessons[popularity].title': 'The Hero’s Popularity', // La popularité {g:du héros|de l’héroïne}
  'tutorial.lessons[popularity].about': 'The popularity gauge: what it gives, where it comes from, why it crumbles.', // La jauge de popularité : ce qu’elle donne, d’où elle vient, pourquoi elle s’effrite.
  'tutorial.lessons[popularity].steps[gauge].say[0].text': 'An order honoured, and {hero} is a little more popular. The gauge is there, under the quest, beside the town’s rank.', // Une commande honorée, et {hero} est un peu plus populaire. Sa jauge est là, sous la quête, à côté du rang de la ville.
  'tutorial.lessons[popularity].steps[gauge].task': 'Open the City, “Rank” tab.', // Ouvrez la Cité, onglet « Rang ».
  'tutorial.lessons[popularity].steps[gives].say[0].text': 'From 0 to 100. The better loved {hero} is, the better the taxes come in, the better the Market’s prices, and every house lodges one more inhabitant every {n:pop_house_step} points.', // De 0 à 100. Plus {hero} est {g:aimé|aimée}, mieux l’impôt rentre, meilleurs sont les prix du Marché, et chaque maison loge un habitant de plus tous les {n:pop_house_step} points.
  'tutorial.lessons[popularity].steps[gives].say[1].text': 'It rises with orders, repelled raids, quests, battles, the keepers’ games, explored sites and great works. A lost raid makes it plummet.', // Elle monte avec les commandes, les raids repoussés, les quêtes, les combats, les jeux des tenanciers, les lieux explorés et les grands chantiers. Un raid perdu la fait chuter.
  'tutorial.lessons[popularity].steps[gives].say[2].text': 'And it crumbles on its own, minute by minute; the higher it is, the slower it climbs. “Where it comes from”, just below, keeps its latest gains.', // Et elle s’effrite toute seule, minute après minute ; plus elle est haute, plus elle monte lentement. « D’où elle vient », juste en dessous, garde ses derniers gains.
  'tutorial.lessons[decor].title': 'Beautifying the Town', // Embellir la ville
  'tutorial.lessons[decor].about': 'Decorations and the beauty of the streets.', // Les décorations et la beauté des rues.
  'tutorial.lessons[decor].steps[flowers].say[0]': 'A handsome street makes its inhabitants more generous: beauty adds to the tax, and the upper classes demand it.', // Une belle rue rend ses habitants plus généreux : la beauté ajoute à l’impôt, et les hautes classes l’exigent.
  'tutorial.lessons[decor].steps[flowers].say[1].text': 'The Decor tab: fountain, well, statue, stall, lamp post, banner, bench, flowers, barrels, hedge. They produce nothing: they beautify.', // L’onglet Décor : fontaine, puits, statue, étal, lampadaire, bannière, banc, fleurs, tonneaux, haie. Ils ne produisent rien : ils embellissent.
  'tutorial.lessons[decor].steps[flowers].task': 'Take the “Flowers” and place them on the glowing tile, near the houses.', // Prenez les « Fleurs » et posez-les sur la case qui brille, près des maisons.
  'tutorial.lessons[decor].steps[street].say[0]': 'Let’s see what the house thinks of it.', // Voyons ce qu’en pense la maison.
  'tutorial.lessons[decor].steps[street].task': 'Click a house, then the “Street” tab.', // Cliquez une maison, puis l’onglet « Rue ».
  'tutorial.lessons[decor].steps[beauty].say[0].text': 'Here, everything that beautifies or spoils it, then how its tax is reckoned. Trees beautify; noisy workshops, like the quarry, spoil.', // Ici, tout ce qui l’embellit ou l’enlaidit, puis le calcul de son impôt. Les arbres embellissent ; les ateliers bruyants, comme la carrière, enlaidissent.
  'tutorial.lessons[decor].steps[beauty].say[1]': 'While you hold a building, a bubble already tells you how many houses it will beautify, or serve.', // Pendant que vous tenez un bâtiment, une bulle dit déjà combien de maisons il embellira, ou servira.
  'tutorial.lessons[panel].title': 'Upgrade, Move, Rotate', // Améliorer, déplacer, tourner
  'tutorial.lessons[panel].about': 'A building’s panel: upgrade, move, demolish, rotate.', // Le panneau d’un bâtiment : améliorer, déplacer, démolir, tourner.
  'tutorial.lessons[panel].steps[upgrade].say[0]': 'Every building can be improved. Let’s open your woodcutter’s hut.', // Chaque bâtiment se perfectionne. Ouvrons votre cabane de bûcheron.
  'tutorial.lessons[panel].steps[upgrade].task': 'Click the Woodcutter’s Hut, then “Upgrade”.', // Cliquez la Cabane de bûcheron, puis « Améliorer ».
  'tutorial.lessons[panel].steps[actions].say[0].text': 'Level 2! Each level produces more; every 5 levels, production doubles and the building changes its look. The Info tab gives the details.', // Niveau 2 ! Chaque niveau produit plus ; tous les 5 niveaux, la production double et le bâtiment change d’apparence. L’onglet Infos le détaille.
  'tutorial.lessons[panel].steps[actions].say[1].text': '“Move” picks it back up on the pointer, losing nothing.', // « Déplacer » le reprend sur le pointeur, sans rien perdre.
  'tutorial.lessons[panel].steps[actions].say[2].text': '“Demolish” razes it and gives you back part of its price.', // « Démolir » le rase et vous rend une partie de son prix.
  'tutorial.lessons[panel].steps[actions].say[3]': 'Lastly, before placing a building or while moving it, the R key (or the “Rotate” button) turns it: its entrance moves to the other side.', // Enfin, avant de poser un bâtiment ou pendant un déplacement, la touche R (ou le bouton « Tourner ») le tourne : son entrée passe de l’autre côté.
  'tutorial.lessons[land].title': 'The Land', // Le terrain
  'tutorial.lessons[land].about': 'Clearing, and planting trees.', // Défricher et planter des arbres.
  'tutorial.lessons[land].steps[clear].say[0].text': 'The Land tab shapes the map: paths, clearing and planting.', // L’onglet Terrain façonne la carte : chemins, défrichage et plantations.
  'tutorial.lessons[land].steps[clear].say[1]': 'Clearing fells a tree or breaks a rock for good, and frees the tile. It also gives back wood or stone.', // Défricher abat un arbre ou brise un rocher pour de bon, et libère la case. Cela rend aussi du bois ou de la pierre.
  'tutorial.lessons[land].steps[clear].task': 'Take “Clear”, then click a tree or a rock.', // Prenez « Défricher », puis cliquez un arbre ou un rocher.
  'tutorial.lessons[land].steps[plant].say[0]': 'The other way round, a tree can be planted for a little gold: oak, maple, birch, fir, willow, palm or bush. Trees beautify the houses nearby.', // À l’inverse, un arbre se plante contre un peu d’or : chêne, érable, bouleau, sapin, saule, palmier ou buisson. Les arbres embellissent les maisons voisines.
  'tutorial.lessons[land].steps[plant].task': 'Take the “Oak” and plant it on the glowing tile.', // Prenez le « Chêne » et plantez-le sur la case qui brille.
  'tutorial.lessons[land].steps[strokes].say[0]': 'Paths, clearing and planting can also be drawn by dragging, tile after tile. And Clear removes a path laid by mistake.', // Chemins, défrichage et plantations se tracent aussi en glissant, case après case. Et Défricher retire un chemin posé par erreur.
  'tutorial.lessons[quests].title': 'The Book of Quests', // Le livre des quêtes
  'tutorial.lessons[quests].about': 'Side quests, the hero’s missions, and contracts.', // Quêtes secondaires, missions {g:du héros|de l’héroïne} et contrats.
  'tutorial.lessons[quests].steps[book].say[0]': 'The quests lead you from chapter to chapter. But the main quest isn’t all there is.', // Les quêtes vous mènent de chapitre en chapitre. Mais il n’y a pas que la quête principale.
  'tutorial.lessons[quests].steps[book].task': 'Open the Quests.', // Ouvrez les Quêtes.
  'tutorial.lessons[quests].steps[side].say[0].text': 'Side quests: extra deliveries and battles, for gold and XP.', // Les quêtes secondaires : des livraisons et des combats en plus, pour de l’or et de l’XP.
  'tutorial.lessons[quests].steps[side].task': 'Open the “Missions” tab.', // Ouvrez l’onglet « Missions ».
  'tutorial.lessons[quests].steps[mission].say[0]': 'A mission sends {hero} off alone for a while: {g:he|she} comes back with XP and loot, even with the game closed. Meanwhile, {g:he|she} isn’t defending the village.', // Une mission envoie {hero} {g:seul|seule} un moment : {g:il|elle} revient avec de l’XP et du butin, même jeu fermé. Pendant ce temps, {g:il|elle} ne défend pas le village.
  'tutorial.lessons[quests].steps[mission].task': 'Start the “Forest Edge Patrol” mission.', // Lancez la mission « Patrouille des lisières ».
  'tutorial.lessons[quests].steps[contracts].say[0].text': 'Contracts come with the “Hold the Village” quest: each victory raises their rank, without limit.', // Les contrats arrivent avec la quête « Tenir le village » : chaque victoire en élève le rang, sans limite.
  'tutorial.lessons[hero].title': '{hero}’s Deck', // Le paquet {de_hero}
  'tutorial.lessons[hero].about': 'The hero’s cards, {g:his|her} battle keys, the forge.', // Les cartes {g:du héros|de l’héroïne}, ses touches de combat, la forge.
  'tutorial.lessons[hero].steps[sheet].say[0]': 'In battle, {hero} plays the cards your buildings send {g:him|her}. The more the village grows, the richer {g:his|her} deck.', // En combat, {hero} joue les cartes que lui envoient vos bâtiments. Plus le village grandit, plus son paquet est riche.
  'tutorial.lessons[hero].steps[sheet].task': 'Open the Hero sheet.', // Ouvrez la fiche {g:du Héros|de l’Héroïne}.
  'tutorial.lessons[hero].steps[deck].say[0].text': '{g:His|Her} deck: one card per standing building, stronger with its level. Untick a card to leave it in the village; further down, the cards to earn, and what gives them.', // Son paquet : une carte par bâtiment debout, plus forte avec son niveau. Décochez une carte pour la laisser au village ; plus bas, celles à gagner, et ce qui les donne.
  'tutorial.lessons[hero].steps[deck].say[1]': 'In battle, each enemy shows above its head what it will do. Keys 1 to 9 play a card, ← and → choose the enemy, Enter ends the turn, Space parries, H opens the rules.', // En combat, chaque ennemi annonce au-dessus de sa tête ce qu’il fera. Les touches 1 à 9 jouent une carte, ← et → choisissent l’ennemi, Entrée finit le tour, Espace pare, H ouvre les règles.
  'tutorial.lessons[hero].steps[deck].say[2]': 'The Forge also makes armour, and better weapons as the quests go on. “Reinforce” gives them +1s.', // La Forge fabrique aussi des armures, et de meilleures armes au fil des quêtes. « Renforcer » leur ajoute des +1.
  'tutorial.lessons[venue].title': 'Visiting a Keeper', // Entrer chez un tenancier
  'tutorial.lessons[venue].about': 'The buildings of a keeper can be visited: a game, medals, a gift.', // Les bâtiments d’un tenancier se visitent : un jeu, des médailles, un cadeau.
  'tutorial.lessons[venue].steps[door].say[0]': 'Some buildings can be visited: the Café, the Market, the Forge, the Bakery, the Barracks… Their panel has an “Enter” button, and inside, their keeper awaits you with a game.', // Certains bâtiments se visitent : le Café, le Marché, la Forge, la Boulangerie, la Caserne… Leur panneau a un bouton « Entrer », et à l’intérieur, leur tenancier vous attend avec un jeu.
  'tutorial.lessons[venue].steps[door].say[1]': 'At the Café, “{game:cafe}”: serve the right cups. At the Forge, “{game:forge}”: strike in rhythm. At the Bakery, “{game:bakery}”: take the bread out nice and golden. At the Barracks, “{game:barracks}”: raise the shield on the right side.', // Au Café, « {game:cafe} » : servir les bonnes tasses. À la Forge, « {game:forge} » : frapper en rythme. À la Boulangerie, « {game:bakery} » : sortir le pain bien doré. À la Caserne, « {game:barracks} » : lever le bouclier du bon côté.
  'tutorial.lessons[venue].steps[door].say[2]': 'A bronze, silver or gold medal makes {hero} more popular, and leaves a gift for {t:venue_buff_time}: better prices, a livelier forge, a better-hammered blade…', // Une médaille de bronze, d’argent ou d’or rend {hero} plus populaire, et laisse un cadeau pendant {t:venue_buff_time} : de meilleurs prix, une forge plus vive, une lame mieux battue…
  'tutorial.lessons[venue].steps[door].say[3]': 'Each game rests for {t:venue_wait} after a round, and grows harder with each win. No entering during a raid. Once inside, I hold my tongue: {keeper} explains the game in person.', // Chaque jeu se repose {t:venue_wait} après une partie, et se corse à chaque victoire. On n’entre pas pendant un raid. Une fois dedans, je me tais : {keeper} explique son jeu lui-même.
  'tutorial.lessons[venue].steps[door].task': 'Click “{venue}”, then “Enter”.', // Cliquez « {venue} », puis « Entrer ».
  'tutorial.lessons[fog].title': 'The Mist and the Scouts', // La brume et les éclaireurs
  'tutorial.lessons[fog].about': 'The mist that hides the lands, and the scouts who lift it.', // La brume qui cache les terres, et les éclaireurs qui la lèvent.
  'tutorial.lessons[fog].steps[open].say[0]': 'Look into the distance: a mist covers the lands. Beneath it, nothing can be built, planted or harvested.', // Regardez au loin : une brume couvre les terres. Dessous, rien ne se bâtit, ne se plante ni ne se récolte.
  'tutorial.lessons[fog].steps[open].say[1]': 'Your buildings push it back around them; your soldiers and {hero} lift it as they march. And to go far, there are the scouts.', // Vos bâtiments la repoussent autour d’eux ; vos soldats et {hero} la lèvent en marchant. Et pour aller loin, il y a les éclaireurs.
  'tutorial.lessons[fog].steps[open].say[2].text': 'Exploration opens here, or with the E key.', // L’Exploration s’ouvre ici, ou avec la touche E.
  'tutorial.lessons[fog].steps[open].task': 'Open Exploration.', // Ouvrez l’Exploration.
  'tutorial.lessons[fog].steps[rose].say[0].text': 'Here, the share of the lands already known.', // Ici, la part des terres déjà connues.
  'tutorial.lessons[fog].steps[rose].say[1].text': 'The scouts’ compass rose: eight directions. Paid in bread and gold, they set out from the town hall, lift the mist along their way, then come home. Each sending goes further, and costs more.', // La rose des éclaireurs : huit directions. Payés en pain et en or, ils partent de l’hôtel de ville, lèvent la brume sur leur chemin, puis rentrent. Chaque envoi va plus loin, et coûte plus cher.
  'tutorial.lessons[fog].steps[rose].say[2]': 'The mist hides sites: ruins, lairs, hamlets, deposits. None lies closer than {n:site_min_dist} tiles to the town hall: only scouts go that far.', // La brume cache des lieux : ruines, tanières, hameaux, gisements. Aucun à moins de {n:site_min_dist} cases de l’hôtel de ville : seuls les éclaireurs vont si loin.
  'tutorial.lessons[fog].steps[send].say[0]': 'Pick a heading, any one at all.', // Choisissez un cap, n’importe lequel.
  'tutorial.lessons[fog].steps[send].task': 'Click a direction on the rose to send out scouts.', // Cliquez une direction de la rose pour envoyer des éclaireurs.
  'tutorial.lessons[fog].steps[gone].say[0]': 'Off they go: follow their pennant on the map. As soon as a site comes out of the mist, I’ll be back to show you what to do with it.', // Les voilà en route : suivez leur fanion sur la carte. Dès qu’un lieu sort de la brume, je reviens vous montrer quoi en faire.
  'tutorial.lessons[barracks].title': 'The Guard', // La garde
  'tutorial.lessons[barracks].about': 'The Barracks and soldiers: training, selecting, sending.', // La Caserne et les soldats : former, choisir, envoyer.
  'tutorial.lessons[barracks].steps[build].say[0]': 'The towers won’t always be enough. The Barracks trains your free inhabitants as soldiers.', // Les tours ne suffiront pas toujours. La Caserne forme vos habitants libres en soldats.
  'tutorial.lessons[barracks].steps[build].task': 'Defence tab: place the “Barracks” on the glowing spot.', // Onglet Défense : posez la « Caserne » sur la place qui brille.
  'tutorial.lessons[barracks].steps[train].say[0].text': 'Clicking the Barracks opens its Soldiers. The Militiaman bars the road: raiders must stop to fight him. The Archer and the Knight will come with the higher classes.', // Un clic sur la Caserne ouvre ses Soldats. Le Milicien barre la route : les pillards doivent s’arrêter pour le combattre. L’Archer et le Chevalier viendront avec les classes plus hautes.
  'tutorial.lessons[barracks].steps[train].task': 'Click the Barracks, then train a “Militiaman”.', // Cliquez la Caserne, puis formez un « Milicien ».
  'tutorial.lessons[barracks].steps[wait].say[0]': 'He drills for a few seconds, then steps out in front of the Barracks.', // Il s’entraîne quelques secondes, puis sort devant la Caserne.
  'tutorial.lessons[barracks].steps[wait].task': 'Wait for the militiaman to be ready.', // Attendez que le milicien soit prêt.
  'tutorial.lessons[barracks].steps[select].say[0]': 'There he is! To give an order, you first select your soldiers.', // Le voilà ! Pour donner un ordre, on choisit d’abord ses soldats.
  'tutorial.lessons[barracks].steps[select].task': 'Press T to select all your soldiers.', // Pressez T pour choisir tous vos soldats.
  'tutorial.lessons[barracks].steps[order].say[0]': 'Once selected, they’re ringed in green. You can also click a soldier, or Shift + drag a box around several.', // Choisis, ils sont cerclés de vert. On peut aussi cliquer un soldat, ou Maj + glisser un cadre autour de plusieurs.
  'tutorial.lessons[barracks].steps[order].task': 'Right-click on the map to send them there.', // Faites un clic droit sur la carte pour les y envoyer.
  'tutorial.lessons[barracks].steps[hold].say[0]': 'They guard the spot and charge raiders who come near. Esc lets them go; “Recall” brings them back before the Barracks. A fallen soldier is lost: another must be trained.', // Ils gardent l’endroit et chargent les pillards qui approchent. Échap les lâche ; « Rappel » les ramène devant la Caserne. Un soldat tombé est perdu : il faut en former un autre.
  'tutorial.lessons[camp].title': 'The Goblin Camp', // Le camp gobelin
  'tutorial.lessons[camp].about': 'Razing the goblin camp with your soldiers; the town hall.', // Raser le camp gobelin avec ses soldats ; l’hôtel de ville.
  'tutorial.lessons[camp].steps[hall].say[0]': 'The goblin camp can fall. Its state and how to attack it are at the town hall.', // Le camp gobelin peut tomber. Son état et la façon de l’attaquer sont à l’hôtel de ville.
  'tutorial.lessons[camp].steps[hall].task': 'Click the town hall, “Village” tab.', // Cliquez l’hôtel de ville, onglet « Village ».
  'tutorial.lessons[camp].steps[attack].say[0].text': '“Attack the camp” sends all your soldiers there; right-clicking the camp with soldiers selected does the same. Its garrison comes out to fight them, then they pull down its palisade.', // « Attaquer le camp » y envoie tous vos soldats ; un clic droit sur le camp, soldats choisis, fait de même. Sa garnison sort les combattre, puis ils abattent sa palissade.
  'tutorial.lessons[camp].steps[attack].say[1]': '{hero} joins them if {g:he’s|she’s} in the village. Once razed, the camp leaves loot and no raid comes for {t:camp_respite}… then another rises further off, stronger, with a chief at its head.', // {hero} les rejoint {g:s’il|si elle} est au village. Rasé, le camp laisse du butin et aucun raid ne vient pendant {t:camp_respite}… puis un autre se dresse plus loin, plus fort, un chef à sa tête.
  'tutorial.lessons[camp].steps[attack].say[2].text': 'The town hall can be upgraded too: each level guards your stores better and widens the safe zone.', // L’hôtel de ville s’améliore aussi : chaque niveau protège mieux vos réserves et élargit la zone sûre.
  'tutorial.lessons[proclaim].title': 'Proclaiming', // Proclamer
  'tutorial.lessons[proclaim].about': 'The town’s ranks: Borough, Town, City, Capital… and what each one opens.', // Les rangs de la ville : Bourg, Ville, Cité, Capitale… et ce que chacun ouvre.
  'tutorial.lessons[proclaim].steps[open].say[0]': 'Aubeval has all it needs to change rank. That calls for a proclamation!', // Aubeval a tout ce qu’il faut pour changer de rang. Cela se proclame !
  'tutorial.lessons[proclaim].steps[open].task': 'Open the City, “Rank” tab.', // Ouvrez la Cité, onglet « Rang ».
  'tutorial.lessons[proclaim].steps[ranks].say[0].text': 'Above the button, what the next rank asks for: inhabitants, houses of a class, honoured orders, repelled raids… then its reward, and what it opens.', // Au-dessus du bouton, ce que le rang suivant demande : des habitants, des maisons d’une classe, des commandes honorées, des raids repoussés… puis sa récompense, et ce qu’il ouvre.
  'tutorial.lessons[proclaim].steps[ranks].say[1]': 'Hamlet, Borough, Town, City, Capital. Each class awaits its rank: Burghers the Borough, Merchants the Town, Nobles the City. The great works too.', // Hameau, Bourg, Ville, Cité, Capitale. Chaque classe attend son rang : les Bourgeois le Bourg, les Négociants la Ville, les Nobles la Cité. Les grands chantiers aussi.
  'tutorial.lessons[proclaim].steps[ranks].say[2]': 'Each rank adds to all production and taxes. And after Capital, they go on without end: Capital II, III…', // Chaque rang ajoute à toute la production et aux impôts. Et après Capitale, ils continuent sans fin : Capitale II, III…
  'tutorial.lessons[proclaim].steps[proclaim].say[0]': 'Everything is ticked: the honour is yours.', // Tout est coché : à vous l’honneur.
  'tutorial.lessons[proclaim].steps[proclaim].task': 'Click “Proclaim”.', // Cliquez « Proclamer ».
  'tutorial.lessons[proclaim].steps[after].say[0]': 'There’s never any hurry: a rank is proclaimed when you wish, and kept… until a new start.', // Rien ne presse jamais : un rang se proclame quand vous le voulez, et se garde… jusqu’à un nouveau départ.
  'tutorial.lessons[site].title': 'A Site Found', // Un lieu trouvé
  'tutorial.lessons[site].about': 'Ruins, lairs, hamlets and deposits: sending the hero there, and calling {g:him|her} back.', // Ruines, tanières, hameaux et gisements : y envoyer {g:le héros|l’héroïne}, et {g:le|la} rappeler.
  'tutorial.lessons[site].steps[open].say[0]': 'The mist has given up a site! It’s on the map, and in Exploration.', // La brume a rendu un lieu ! Il est sur la carte, et dans l’Exploration.
  'tutorial.lessons[site].steps[open].task': 'Open Exploration (E key).', // Ouvrez l’Exploration (touche E).
  'tutorial.lessons[site].steps[see].say[0].text': 'Each site found has its own line: its name, its level, its distance, and what is happening there. “View” brings the view onto it.', // Chaque lieu trouvé a sa ligne : son nom, son niveau, sa distance, et ce qui s’y passe. « Voir » amène la vue dessus.
  'tutorial.lessons[site].steps[see].task': 'Click “View”.', // Cliquez « Voir ».
  'tutorial.lessons[site].steps[page].say[0]': 'There it is. A click on the site, on the map or on its line, opens its page.', // Le voilà. Un clic sur le lieu, sur la carte ou sur sa ligne, ouvre sa page.
  'tutorial.lessons[site].steps[page].task': 'Click the site’s line.', // Cliquez la ligne du lieu.
  'tutorial.lessons[site].steps[kinds].say[0]': 'Four kinds of site. A ruin: a single battle, and it’s explored for good. A lair: once emptied, it fills up again, stronger each time.', // Quatre sortes de lieux. Une ruine : un seul combat, et elle est explorée pour de bon. Une tanière : vidée, elle se repeuple, plus forte à chaque fois.
  'tutorial.lessons[site].steps[kinds].say[1]': 'A hamlet: a first gift opens a trade route, and each delivery swells its pay. A deposit: once claimed, it sends its yield every minute, and digs deeper.', // Un hameau : un premier présent ouvre une route de commerce, et chaque livraison grossit sa paie. Un gisement : revendiqué, il envoie sa récolte chaque minute, et se creuse.
  'tutorial.lessons[site].steps[kinds].say[2].text': '{hero} must first travel there: on the way, {g:he|she} no longer guards the village. On site, nothing starts by itself: a battle only begins on “Fight”. And “Return” calls {g:him|her} back at any time.', // {hero} doit d’abord s’y rendre : pendant le trajet, {g:il|elle} ne garde plus le village. Sur place, rien ne part tout seul : un combat ne commence que sur « Combattre ». Et « Rentrer » {g:le|la} rappelle à tout moment.
  'tutorial.lessons[site].steps[go].say[0]': 'Let’s send {g:him|her} to look.', // Envoyons-{g:le|la} voir.
  'tutorial.lessons[site].steps[go].task': 'Click “Go there”.', // Cliquez « Y aller ».
  'tutorial.lessons[site].steps[back].say[0]': 'When {g:he|she} arrives, a message will let you know: then reopen the site’s page. Meanwhile, let’s go back to the list.', // À son arrivée, un message vous prévient : rouvrez alors la page du lieu. En attendant, revenons à la liste.
  'tutorial.lessons[site].steps[back].task': 'Click “‹ All sites”.', // Cliquez « ‹ Tous les lieux ».
  'tutorial.lessons[site].steps[trip].say[0].text': '{g:His|Her} expedition can be followed here: how far along {g:he|she} is, and the time left.', // Son expédition se suit ici : où {g:il|elle} en est, et le temps qu’il reste.
  'tutorial.lessons[site].steps[trip].say[1].text': '“Return”: {g:he|she} turns back, and takes up {g:his|her} guard before the town hall when {g:he|she} arrives.', // « Rentrer » : {g:il|elle} fait demi-tour, et reprend sa garde devant l’hôtel de ville en arrivant.
  'tutorial.lessons[site].steps[trip].say[2]': 'Trade routes and deposits bring something in every minute, even with the game closed. Safe travels, {hero}!', // Les routes et les gisements rapportent chaque minute, même jeu fermé. Bonne route, {hero} !
  'tutorial.lessons[chief].title': 'The Camp’s Chief', // Le chef du camp
  'tutorial.lessons[chief].about': 'Camps that rise again have a chief: tougher, and with a price on his head.', // Les camps qui se relèvent ont un chef : plus coriace, et sa tête a un prix.
  'tutorial.lessons[chief].steps[hall].say[0]': 'A new camp has risen, further off and stronger. And this time a chief commands it: {chief}.', // Un nouveau camp s’est dressé, plus loin, plus fort. Et cette fois un chef y commande : {chief}.
  'tutorial.lessons[chief].steps[hall].task': 'Click the town hall, “Village” tab.', // Cliquez l’hôtel de ville, onglet « Village ».
  'tutorial.lessons[chief].steps[chief].say[0].text': 'Here he is: his name, his health, and what his head adds to the loot. He stands before the camp gate, tougher than his guards, and hits harder with each camp.', // Le voici : son nom, sa vie, et ce que sa tête ajoute au butin. Il se tient devant la porte du camp, plus coriace que ses gardes, et frappe plus fort à chaque camp.
  'tutorial.lessons[chief].steps[chief].say[1].text': 'The palisade only falls once the garrison is down, chief included. Send enough soldiers; {hero} joins them if {g:he’s|she’s} in the village.', // La palissade ne tombe qu’une fois la garnison à terre, chef compris. Envoyez assez de soldats ; {hero} les rejoint {g:s’il|si elle} est au village.
  'tutorial.lessons[quarry].title': 'Stone', // La pierre
  'tutorial.lessons[quarry].about': 'The noisy Quarry, and the rocks.', // La Carrière, bruyante, et les rochers.
  'tutorial.lessons[quarry].steps[quarry].say[0]': 'Twelve inhabitants: the Quarry opens. It cuts the stone for chapels, mage towers and second-tier weapons.', // Douze habitants : la Carrière s’ouvre. Elle taille la pierre des chapelles, des tours de mage et des armes du deuxième palier.
  'tutorial.lessons[quarry].steps[quarry].say[1]': 'It’s noisy: it spoils the houses around it.', // Elle est bruyante : elle enlaidit les maisons autour.
  'tutorial.lessons[quarry].steps[quarry].say[2].text': 'I’ve found you a spot set apart, with the other workshops; if need be, we’ll run a bit of path to it.', // Je vous ai trouvé une place à l’écart, avec les autres ateliers ; s’il le faut, on y mène un bout de chemin.
  'tutorial.lessons[quarry].steps[quarry].task': 'Production tab: place a “Quarry” on the glowing spot, away from the houses.', // Onglet Production : posez une « Carrière » sur la place qui brille, à l’écart des maisons.
  'tutorial.lessons[quarry].steps[rocks].say[0]': 'Miners, trained from the People panel, also bring back stone from the rocks; clicking a rock gives a little by hand.', // Les Mineurs, formés depuis le Peuple, rapportent aussi la pierre des rochers ; un clic sur un rocher en donne un peu à la main.
  'tutorial.lessons[coffee].title': 'Coffee and the Artisans', // Le café et les Artisans
  'tutorial.lessons[coffee].about': 'The coffee chain, services within reach, raising a house.', // La chaîne du café, les services à portée, élever une maison.
  'tutorial.lessons[coffee].steps[cafe].say[0]': 'Twenty-four inhabitants: coffee arrives. The Coffee Plantation gives the beans, the Roastery roasts them into coffee.', // Vingt-quatre habitants : le café arrive. La Plantation de caféiers donne les grains, la Brûlerie les torréfie en café.
  'tutorial.lessons[coffee].steps[cafe].say[1]': 'Your Peasants, fed on bread and coffee, with a Café down the street, will be able to rise to Artisans.', // Vos Paysans, nourris de pain et de café, avec un Café au bout de la rue, pourront s’élever en Artisans.
  'tutorial.lessons[coffee].steps[cafe].say[2].text': 'The Café is a service: it serves the houses within its radius. While you hold it, you’ll see that radius, with the houses served outlined.', // Le Café est un service : il sert les maisons dans son rayon. En le tenant, vous verrez ce rayon et les maisons servies encadrées.
  'tutorial.lessons[coffee].steps[cafe].task': 'Housing tab: place a “Café” on the glowing spot, among your houses.', // Onglet Habitat : posez un « Café » sur la place qui brille, parmi vos maisons.
  'tutorial.lessons[coffee].steps[house].say[0]': 'When a house has everything it needs, its satisfaction fills up.', // Quand une maison a tout ce qu’il lui faut, sa satisfaction se remplit.
  'tutorial.lessons[coffee].steps[house].task': 'Click a house, “Inhabitants” tab.', // Cliquez une maison, onglet « Habitants ».
  'tutorial.lessons[coffee].steps[raise].say[0].text': 'Here, what it needs to rise. All ticked, “Raise” moves it up to the next class: more inhabitants, more tax, a bigger house.', // Ici, ce qu’il lui faut pour s’élever. Tout coché, « Élever » la fait passer à la classe suivante : plus d’habitants, plus d’impôt, une maison plus grande.
  'tutorial.lessons[coffee].steps[raise].say[1].text': 'The Mage Tower opens too: a lightning bolt that pierces armour, for a Rune Shard brought back from quests.', // La Tour de mage s’ouvre aussi : un éclair qui perce les armures, contre un Éclat rapporté des quêtes.
  'tutorial.lessons[taxes].title': 'Taxes', // Les impôts
  'tutorial.lessons[taxes].about': 'A tax level per class: low, normal or high, and what each one costs.', // Un niveau d’impôt par classe : bas, normal ou élevé, et ce que chacun coûte.
  'tutorial.lessons[taxes].steps[hall].say[0]': 'Your Artisans pay well. But tax can be set, class by class: that is decided at the town hall.', // Vos Artisans paient bien. Mais l’impôt se règle, classe par classe : cela se décide à l’hôtel de ville.
  'tutorial.lessons[taxes].steps[hall].task': 'Click the town hall, “Taxes” tab.', // Cliquez l’hôtel de ville, onglet « Impôts ».
  'tutorial.lessons[taxes].steps[levels].say[0].text': 'One line per class, three levels. Each button shows what the class would pay per minute at that level.', // Une ligne par classe, trois niveaux. Chaque bouton affiche ce que la classe paierait par minute à ce niveau.
  'tutorial.lessons[taxes].steps[levels].say[1].text': 'High: more gold right away. But satisfaction is capped, those houses no longer rise, and {hero} loses popularity, minute by minute.', // Élevé : plus d’or tout de suite. Mais la satisfaction plafonne, ces maisons ne s’élèvent plus, et {hero} y perd de la popularité, minute après minute.
  'tutorial.lessons[taxes].steps[levels].say[2].text': 'Low: less gold, but satisfaction rises {n:tax_low_sat} times faster, and the class rises sooner. Perfect before raising houses.', // Bas : moins d’or, mais la satisfaction monte {n:tax_low_sat} fois plus vite, et la classe s’élève plus tôt. Parfait avant de faire monter des maisons.
  'tutorial.lessons[taxes].steps[levels].task': 'Pick a level for this class: Low, Normal or High.', // Choisissez un niveau pour cette classe : Bas, Normal ou Élevé.
  'tutorial.lessons[taxes].steps[after].say[0]': 'You can change it at any time, free of charge. The City (G) has the same setting, in its “Taxes” tab.', // Cela se change à tout moment, sans frais. La Cité (G) a le même réglage, dans son onglet « Impôts ».
  'tutorial.lessons[market].title': 'The Market and the Chapel', // Le Marché et la Chapelle
  'tutorial.lessons[market].about': 'Buying, selling, importing spices; the Chapel.', // Acheter, vendre, importer des épices ; la Chapelle.
  'tutorial.lessons[market].steps[market].say[0]': 'Four Artisan houses: the Market and the Chapel open.', // Quatre maisons d’Artisans : le Marché et la Chapelle s’ouvrent.
  'tutorial.lessons[market].steps[market].say[1]': 'The Market buys and sells your stores for gold, and its caravans import the Burghers’ spices.', // Le Marché achète et vend vos réserves contre de l’or, et ses caravanes importent les épices des Bourgeois.
  'tutorial.lessons[market].steps[market].task': 'Housing tab: place a “Market” on the glowing spot.', // Onglet Habitat : posez un « Marché » sur la place qui brille.
  'tutorial.lessons[market].steps[stalls].say[0]': 'Let’s look at its stalls.', // Voyons ses étals.
  'tutorial.lessons[market].steps[stalls].task': 'Click the Market, “Trade” tab.', // Cliquez le Marché, onglet « Commerce ».
  'tutorial.lessons[market].steps[trade].say[0].text': 'Spices cost gold: this button pauses the import.', // Les épices coûtent de l’or : ce bouton met l’import en pause.
  'tutorial.lessons[market].steps[trade].say[1].text': 'Each line buys or sells a lot of one resource.', // Chaque ligne achète ou vend un lot d’une ressource.
  'tutorial.lessons[market].steps[trade].say[2].text': 'The Market can be visited too: “Enter”, and its merchant challenges you to haggle. Win a medal, and her prices smile on you for a while.', // Le Marché se visite aussi : « Entrer », et sa marchande vous défie au marchandage. Une médaille, et ses prix vous sourient un moment.
  'tutorial.lessons[market].steps[trade].say[3].text': 'The Chapel is a service with a wide radius: Burghers want it within reach, along with the Café, spices on the table… and a town of Borough rank.', // La Chapelle est un service à grand rayon : les Bourgeois la veulent à portée, avec le Café, des épices à table… et une ville au rang de Bourg.
  'tutorial.lessons[cloth].title': 'Wool and Cloth', // Laine et étoffes
  'tutorial.lessons[cloth].about': 'Sheepfold, weaving, and the Merchants.', // Bergerie, tissage, et les Négociants.
  'tutorial.lessons[cloth].steps[sheep].say[0]': 'Four Burgher houses: wool arrives. The Sheepfold raises sheep, the Weaving Workshop weaves the wool into cloth.', // Quatre maisons de Bourgeois : la laine arrive. La Bergerie élève les moutons, l’Atelier de tissage tisse la laine en étoffes.
  'tutorial.lessons[cloth].steps[sheep].say[1]': 'Cloth makes Merchants, who also want the Market within reach, a pleasant street, and a town of Town rank.', // Les étoffes font des Négociants, qui veulent aussi le Marché à portée, une rue plaisante, et une ville au rang de Ville.
  'tutorial.lessons[cloth].steps[sheep].task': 'Production tab: place a “Sheepfold” on the glowing spot.', // Onglet Production : posez une « Bergerie » sur la place qui brille.
  'tutorial.lessons[cloth].steps[weaver].say[0].text': 'Then the Weaving Workshop, next to it: it takes two wool for one cloth.', // Puis l’Atelier de tissage, à côté : il mange deux laines pour une étoffe.
  'tutorial.lessons[jewels].title': 'The Nobles’ Jewels', // Les bijoux des Nobles
  'tutorial.lessons[jewels].about': 'The Goldsmith and the highest class.', // L’Orfèvre et la plus haute classe.
  'tutorial.lessons[jewels].steps[goldsmith].say[0].text': 'Four Merchant houses: the Goldsmith turns gold and stone into jewels.', // Quatre maisons de Négociants : l’Orfèvre change l’or et la pierre en bijoux.
  'tutorial.lessons[jewels].steps[goldsmith].say[1]': 'Jewels, with a superb street — fountains, statues, trees and flowers — make Nobles, the highest class in Aubeval. They need City rank, and a popular hero.', // Les bijoux, avec une rue superbe — fontaines, statues, arbres et fleurs —, font des Nobles, la plus haute classe d’Aubeval. Il leur faut le rang de Cité, et {g:un héros|une héroïne} populaire.
  'tutorial.lessons[lodge].title': 'The Builders’ Lodge', // La Loge des bâtisseurs
  'tutorial.lessons[lodge].about': 'Aveline’s Lodge: her game of the quarter to rebuild, and her plans that make building cheaper.', // La Loge d’Aveline : son jeu du quartier à rebâtir, et ses plans qui font bâtir moins cher.
  'tutorial.lessons[lodge].steps[lodge].say[0]': 'Aubeval is a Town, burgomaster: its builders deserve their Lodge. Mine, at last! There is only one, and that is where I will draw up your plans.', // Aubeval est une Ville, bourgmestre : ses bâtisseurs méritent leur Loge. La mienne, enfin ! Il n’y en a qu’une, et c’est là que je dresserai vos plans.
  'tutorial.lessons[lodge].steps[lodge].task': 'Housing tab: place the “Lodge” on the glowing spot.', // Onglet Habitat : posez la « Loge » sur la place qui brille.
  'tutorial.lessons[lodge].steps[stone].say[0]': 'The Lodge can be visited, like the Café: “Enter”, and I will be waiting for you inside with “{game:lodge}”. I show you a small quarter, then I hide it: it is up to you to rebuild it from memory.', // La Loge se visite, comme le Café : « Entrer », et je vous y attends avec « {game:lodge} ». Je vous montre un petit quartier, puis je le cache : à vous de le rebâtir de mémoire.
  'tutorial.lessons[lodge].steps[stone].say[1]': 'A medal, and my plans are yours for a while: buildings and upgrades cost less. Each level of the Lodge makes them last longer.', // Une médaille, et mes plans sont à vous un moment : constructions et améliorations moins chères. Chaque niveau de la Loge les fait durer plus longtemps.
  'tutorial.lessons[lodge].steps[stone].say[2]': 'And the Lodge itself, as soon as it stands, makes you build a little cheaper, repair for less and recover more when you demolish. The higher it climbs, the clearer it gets.', // Et la Loge elle-même, dès qu’elle est posée, vous fait bâtir un peu moins cher, réparer à meilleur compte et récupérer davantage en démolissant. Plus elle monte, plus c’est net.
  'tutorial.lessons[works].title': 'The Great Works', // Les grands chantiers
  'tutorial.lessons[works].about': 'Cathedral, Castle, Great Lighthouse: stages, a permanent bonus, endless embellishments.', // Cathédrale, Château, Grand phare : des étapes, un bonus permanent, des embellissements sans fin.
  'tutorial.lessons[works].steps[found].say[0]': 'Aubeval is a Town: it can think big. A great work swallows your surplus for hours, and in return gives a permanent bonus to the whole town.', // Aubeval est une Ville : elle peut voir grand. Un grand chantier avale vos surplus pendant des heures, et donne en échange un bonus permanent à toute la ville.
  'tutorial.lessons[works].steps[found].say[1].text': 'They have their own tab: the Cathedral first, the Castle at City rank, the Great Lighthouse at Capital. Only one of each.', // Ils ont leur onglet : la Cathédrale d’abord, le Château au rang de Cité, le Grand phare à celui de Capitale. Un seul de chaque.
  'tutorial.lessons[works].steps[found].say[2].text': 'Placing it means pouring its foundations. I’ll show you a spot worthy of it: wide, near the houses it will beautify.', // La poser, c’est couler ses fondations. Je vous montre une place digne d’elle : large, près des maisons qu’elle embellira.
  'tutorial.lessons[works].steps[found].task': 'Great Works tab: place the “Cathedral” on the glowing spot (or elsewhere).', // Onglet Chantiers : posez la « Cathédrale » sur la place qui brille (ou ailleurs).
  'tutorial.lessons[works].steps[open].say[0]': 'The foundations are poured. Let’s see the works.', // Les fondations sont coulées. Voyons le chantier.
  'tutorial.lessons[works].steps[open].task': 'Click the Cathedral, “Works” tab.', // Cliquez la Cathédrale, onglet « Chantier ».
  'tutorial.lessons[works].steps[stages].say[0].text': 'Four stages: Foundations, Walls, Roof, Completion. Each costs thousands of resources, changes the monument on the map, and adds to what it gives. This button pays for the next.', // Quatre étapes : Fondations, Murs, Toiture, Achèvement. Chacune coûte des milliers de ressources, change le monument sur la carte, et ajoute à ce qu’il donne. Ce bouton paie la suivante.
  'tutorial.lessons[works].steps[stages].say[1]': 'The Cathedral makes meals happier and holds on to {hero}’s popularity; the Castle shelters your stores and hardens your soldiers; the Lighthouse improves Market prices, sight in the mist and expeditions.', // La Cathédrale rend les repas plus heureux et retient la popularité {de_hero} ; le Château met vos réserves à l’abri et endurcit vos soldats ; le Phare améliore les prix du Marché, la vue dans la brume et les expéditions.
  'tutorial.lessons[works].steps[stages].say[2]': 'Once complete, the work goes on: embellishments without end, each a little dearer, each a little more bonus. The City (G), “Great Works” tab, gathers all three monuments.', // Achevé, le chantier continue : des embellissements, sans fin, chacun un peu plus cher, chacun un peu de bonus en plus. La Cité (G), onglet « Chantiers », réunit les trois monuments.
  'tutorial.lessons[works].steps[build].say[0]': 'You can afford the next stage: start it!', // Vous avez de quoi payer l’étape suivante : lancez-la !
  'tutorial.lessons[works].steps[build].task': 'Click the works button.', // Cliquez le bouton du chantier.
  'tutorial.lessons[register].title': 'The Village Register', // Le registre du village
  'tutorial.lessons[register].about': 'Saving, offline gains, the new start, this book.', // Sauvegarde, gains hors-ligne, nouveau départ, ce livre.
  'tutorial.lessons[register].steps[menu].say[0]': 'One last secret: the village register.', // Un dernier secret : le registre du village.
  'tutorial.lessons[register].steps[menu].task': 'Open the Village (V key).', // Ouvrez le Village (touche V).
  'tutorial.lessons[register].steps[save].say[0].text': 'Aubeval saves itself in this browser. Export the file to keep it elsewhere; import it to pick up again.', // Aubeval se sauvegarde seul dans ce navigateur. Exportez le fichier pour le garder ailleurs ; importez-le pour reprendre.
  'tutorial.lessons[register].steps[save].say[1]': 'With the game closed, the village keeps producing: when you return, I’ll tell you what it earned.', // Jeu fermé, le village continue de produire : à votre retour, je vous dirai ce qu’il a gagné.
  'tutorial.lessons[register].steps[save].say[2].text': 'When growth slows, a New Start trades the village for Renown, kept for ever. The City (G), “Legacy” tab, shows what remains and where to spend it: I’ll show you everything there.', // Quand la croissance ralentit, un Nouveau départ échange le village contre de la Renommée, gardée pour toujours. La Cité (G), onglet « Héritage », dit ce qui reste et où la dépenser : je vous y montrerai tout.
  'tutorial.lessons[register].steps[save].say[3].text': 'And here is the Book of Lessons: all my lessons, to revisit whenever you like.', // Et voici le Livre des leçons : toutes mes leçons, à revoir quand vous voulez.
  'tutorial.lessons[legacy].title': 'Legacy and the New Start', // L’héritage et le nouveau départ
  'tutorial.lessons[legacy].about': 'The Renown of a new start, and the tree of bonuses it buys for ever.', // La Renommée d’un nouveau départ, et l’arbre de bonus qu’elle achète pour toujours.
  'tutorial.lessons[legacy].steps[open].say[0]': 'A village can start all over… and come out stronger. That is the legacy.', // Un village peut tout recommencer… et en sortir plus fort. C’est l’héritage.
  'tutorial.lessons[legacy].steps[open].task': 'Open the City, “Legacy” tab.', // Ouvrez la Cité, onglet « Héritage ».
  'tutorial.lessons[legacy].steps[start].say[0].text': 'A new start trades this village for Renown: so much for the gold earned, so much for the rank reached. It’s the same button as in the Village (V) register.', // Un nouveau départ échange ce village contre de la Renommée : tant pour l’or gagné, tant pour le rang atteint. C’est le même bouton que celui du registre du Village (V).
  'tutorial.lessons[legacy].steps[start].say[1]': 'What stays: {hero}, {g:his|her} quests, the legacy, the sites discovered. What starts from scratch: buildings, stores, rank, orders, taxes and works. No hurry: it takes two clicks, and I’ll never rush you into it.', // Restent : {hero}, ses quêtes, l’héritage, les lieux découverts. Repartent de zéro : bâtiments, réserves, rang, commandes, impôts et chantiers. Rien ne presse : il demande deux clics, et je ne vous le fais pas presser.
  'tutorial.lessons[legacy].steps[start].say[2].text': 'Renown is never lost, and each point adds to all production. Spent here, it also buys bonuses that count for this village and every one after.', // La Renommée ne se perd jamais, et chaque point ajoute à toute la production. Dépensée ici, elle achète en plus des bonus qui valent pour ce village et tous les suivants.
  'tutorial.lessons[legacy].steps[start].say[3]': 'Three branches: Prosperity, Arms, Horizons. A node opens when the one before it has the level required, and each level costs a little more.', // Trois branches : Prospérité, Armes, Horizons. Un nœud s’ouvre quand celui d’avant a le niveau demandé, et chaque niveau coûte un peu plus.
  'tutorial.lessons[legacy].steps[learn].say[0]': 'You have Renown to spend: let’s learn a first level.', // Vous avez de la Renommée à dépenser : apprenons un premier niveau.
  'tutorial.lessons[legacy].steps[learn].task': 'Click “+1” on the node the arrow points to.', // Cliquez « +1 » sur le nœud que la flèche montre.
});
